function liveStatusMarkup(){return `<span class="live-status${LIVE.status==='Live'?' is-live':LIVE.status==='Offline'?' is-offline':''}" data-live-status role="status" aria-label="Automatic updates">${e(LIVE.status)}</span>`;}
